def bury_siblings(cards: tuple[Card, ...], reviewed_card_id: str, today: date) -> tuple[Card, ...]:
    reviewed_card_index = next((index for index, card in enumerate(cards) if card.id == reviewed_card_id), None)

    if reviewed_card_index is None:
        return cards  # Return the original tuple if the reviewed card is not found

    reviewed_card = cards[reviewed_card_index]
    note_id = reviewed_card.note_id

    updated_cards = []

    for card in cards:
        if card.note_id == note_id and card.id != reviewed_card_id and card.state != CardState.SUSPENDED:
            buried_until = card.buried_until
            if buried_until is None or buried_until < today:
                updated_card = dataclasses.replace(card, buried_until=today)
                updated_cards.append(updated_card)
            else:
                updated_cards.append(card)
        else:
            updated_cards.append(card)

    return tuple(updated_cards)

